  font-size:12px;line-height:20px;color:#a1a1a6;position:relative;z-index:2}

/* 标签 */
.xt-root .xt-content .xt-tags{display:grid!important;grid-template-columns:repeat(3,1fr);height:38px;margin:0!important;padding:0!important;gap:0!important;background:#000!important;border:0!important;
  border-radius:0!important;box-shadow:inset 0 -1px 0 #262626!important;overflow:hidden;animation:none!important}
.xt-root .xt-content .xt-tags .xt-tag{display:flex;align-items:center;justify-content:center;margin:0!important;padding:0!important;border:0!important;border-radius:0!important;
  font-size:14.5px;letter-spacing:.5px;animation:none!important;transition:color .2s;background:none}
.xt-root .xt-content .xt-tags .xt-tag:nth-child(1){color:var(--tc0);font-weight:var(--tw0);background:var(--tu0)}
.xt-root .xt-content .xt-tags .xt-tag:nth-child(2){color:var(--tc1);font-weight:var(--tw1);background:var(--tu1)}
.xt-root .xt-content .xt-tags .xt-tag:nth-child(3){color:var(--tc2);font-weight:var(--tw2);background:var(--tu2)}
.xt-content{--p0:block;--p1:none;--p2:none;--p3:none;--l1:33.3333%;--l2:66.6667%;--l3:-300%;
  --tc0:#fff;--tc1:#8e8e93;--tc2:#8e8e93;--tw0:700;--tw1:500;--tw2:500;
  --tu0:linear-gradient(#fff,#fff) center bottom/100% 2px no-repeat;--tu1:linear-gradient(transparent,transparent);--tu2:linear-gradient(transparent,transparent)}
.xt-action-1,.xt-action-2,.xt-action-3{display:block;position:absolute;top:48px;height:38px;width:33.3333%;margin:0;padding:0;border:none;
  background:transparent;opacity:0;z-index:20;cursor:pointer;-webkit-tap-highlight-color:transparent}
.xt-action-1{left:var(--l1)}.xt-action-2{left:var(--l2)}.xt-action-3{left:var(--l3)}
.xt-action-1::after,.xt-action-2::after,.xt-action-3::after{content:""}

/* 页面容器 */
.xt-root .xt-content .xt-collapse{display:block!important;margin:0!important;padding:0!important;border:0!important;border-radius:0!important;background:#000!important;box-shadow:none!important;
  height:430px;overflow-y:auto;overflow-x:hidden;-webkit-overflow-scrolling:touch;overscroll-behavior:contain;touch-action:pan-y}
.xt-root .xt-content .xt-collapse-header{display:none!important}
.xt-root .xt-content .xt-collapse-body{display:block!important;max-height:none!important;overflow:visible!important;padding:2px 0 0!important;margin:0!important;opacity:1!important;border:0!important}
.xt-root .xt-content .xt-collapse-body::after{content:"";display:block;height:12px}
.xt-root .xt-content .xt-collapse::-webkit-scrollbar{width:2px}
.xt-root .xt-content .xt-collapse::-webkit-scrollbar-thumb{background:#48484a;border-radius:2px}
.xt-root .xt-content .xt-collapse-4{display:var(--p0)!important}
.xt-root .xt-content .xt-collapse-5{display:var(--p1)!important}
.xt-root .xt-content .xt-collapse-6{display:var(--p2)!important}

/* 卡片 */
.xt-root .xt-content .xt-collapse .xt-card{display:block;position:relative;margin:12px 12px 14px!important;padding:0!important;border:1px solid #2a2a2c!important;border-radius:18px!important;overflow:hidden;
  background:#161618!important;box-shadow:none!important;animation:none!important}
.xt-root .xt-content .xt-collapse .xt-card .xt-text{display:block;margin:0;padding:0;border:0;border-radius:0;background:none;box-shadow:none;text-align:left;letter-spacing:0;font-style:normal;animation:none}
.xt-root .xt-content .xt-collapse .xt-card::after{content:"";display:block;clear:both;height:9px}
