.xt-content{position:relative;display:block!important;padding:0!important;gap:0!important}
.xt-content>*{margin:0!important}
.xt-content::before{content:"";position:absolute;left:0;right:0;top:-30px;height:30px;z-index:30;pointer-events:none;
  background:linear-gradient(90deg,transparent 0.00% 2.60%,#fff 2.60% 20.28%,transparent 20.28% 21.88%,#fff 21.88% 39.56%,transparent 39.56% 41.16%,#fff 41.16% 58.84%,transparent 58.84% 60.44%,#fff 60.44% 78.12%,transparent 78.12% 79.72%,#fff 79.72% 97.40%,transparent 97.40% 100%) 0 11px/100% 2.6px no-repeat;-webkit-clip-path:inset(0 100% 0 0);clip-path:inset(0 100% 0 0);animation:xtstory 12s linear infinite}
