  background:none!important;border:0!important;border-radius:0!important;box-shadow:none!important}
.xt-root .xt-content .xt-row>*{flex:none!important;width:auto!important;margin:0!important;padding:0!important;background:none!important;border:0!important;box-shadow:none!important}
