.xt-root{position:relative;overflow:hidden;border:none!important;padding:0!important;border-radius:14px;background:#000!important;box-shadow:0 6px 22px rgba(0,0,0,.4);
  font-family:-apple-system,"Helvetica Neue","PingFang SC","Noto Sans CJK SC","Microsoft YaHei",sans-serif}
